package com.personal.jobagent.identity;
import com.personal.jobagent.common.UuidV7; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.util.*;
@Service public class IdentityService { private final JdbcTemplate db; public IdentityService(JdbcTemplate db){this.db=db;} public UUID create(UUID profileId,String email,String domain,String credentialRef){UUID id=UuidV7.generate();db.update("insert into applicant_identities(id,profile_id,applicant_email,credential_ref,domain) values(?,?,?,?,?) on conflict(profile_id,domain) do update set applicant_email=excluded.applicant_email,credential_ref=excluded.credential_ref,updated_at=now()",id,profileId,email,credentialRef,domain);return db.queryForObject("select id from applicant_identities where profile_id=? and domain=?",UUID.class,profileId,domain);} public UUID startSession(UUID applicationId,String expectedDomain){UUID id=UuidV7.generate();db.update("insert into account_sessions(id,application_id,expected_domain,state) values(?,?,?,'DISCOVER')",id,applicationId,expectedDomain);db.update("update applications set account_session_id=? where id=?",id,applicationId);return id;} public boolean transition(UUID id,String from,String to){return db.update("update account_sessions set state=?,updated_at=now() where id=? and state=?",to,id,from)==1;} public boolean hardStop(UUID id,String reason){return db.update("update account_sessions set state='HARD_STOP',hard_stop_reason=?,updated_at=now() where id=? and state not in ('COMPLETED','HARD_STOP')",reason,id)==1;} public Map<String,Object> session(UUID id){return db.queryForMap("select id,application_id,applicant_identity_id,automation_plan_id,state,expected_domain,hard_stop_reason,created_at,updated_at from account_sessions where id=?",id);} }